<script setup lang="ts">
import { computed } from 'vue'
import type { JsonValue } from '~/types/generation'
import { safeSourceUrl } from '~/utils/provenance'
const props = defineProps<{ value?: JsonValue }>()
defineEmits<{ inspect: [id: string] }>()
const claims = computed(() => Array.isArray(props.value) ? props.value.filter(v => v && typeof v === 'object' && !Array.isArray(v)) as Record<string, JsonValue>[] : [])
function evidence(claim: Record<string, JsonValue>) { return Array.isArray(claim.evidence_records) ? claim.evidence_records.filter(v => v && typeof v === 'object' && !Array.isArray(v)) as Record<string, JsonValue>[] : [] }
function status(claim: Record<string, JsonValue>) { const supported = evidence(claim).some(e => e.verification_status === 'verified_authentic' && e.is_detached !== true && typeof e.citation_locator === 'string' && e.citation_locator.trim() && e.verified_at); return claim.server_verification_status === 'verified_authentic' && supported ? { label: 'Снимок: свидетельство сопоставлено с выделенным утверждением', tone: 'neutral' as const } : { label: 'Культурный факт требует проверки', tone: 'warning' as const } }
function id(value: JsonValue | undefined) { return typeof value === 'string' && /^[a-f0-9-]{36}$/i.test(value) ? value : null }
</script>
<template><div class="scenario-claims"><UiAlert tone="warning">Модерация сценария не подтверждает каждый исторический факт. Ниже — сохранённые серверные статусы и доказательства; актуальные сведения проверяйте в первоисточнике.</UiAlert><p v-if="!claims.length" class="muted">Список заявленных культурных утверждений пуст. Исторические сведения могут находиться в других разделах; требуется проверка всего текста.</p><article v-for="(claim, i) in claims" :key="i" class="scenario-claim"><ProvenanceStatus :state="status(claim)" /><h3>{{ claim.culture_name }}</h3><p>{{ claim.claim_text }}</p><p class="muted">Сопоставление источника относится только к выделенному утверждению. Остальные сведения и трактовки проверяются отдельно.</p><p v-if="claim.claimed_origin">Происхождение (описание модели): {{ claim.claimed_origin }}</p><p v-if="claim.claimed_meaning">Трактовка модели — требуется проверка: {{ claim.claimed_meaning }}</p><p v-if="!evidence(claim).length">Прикреплённых серверных доказательств нет.</p><div v-for="(item, j) in evidence(claim)" :key="j" class="scenario-evidence"><strong>{{ item.source_title || 'Первоисточник' }}</strong><p>Локатор: {{ item.citation_locator || 'Не указан' }}</p><blockquote v-if="item.citation_excerpt">{{ item.citation_excerpt }}</blockquote><p v-if="item.verified_at" class="muted">Проверено в сохранённом снимке: {{ item.verified_at }}</p><button v-if="id(item.event_source_id)" type="button" class="text-button" @click="$emit('inspect', id(item.event_source_id)!)">Открыть актуальные сведения об источнике</button><a v-if="typeof item.url === 'string' && safeSourceUrl(item.url)" :href="safeSourceUrl(item.url)" target="_blank" rel="noopener noreferrer">Внешний первоисточник ↗</a></div></article></div></template>
